# Initially generated by GitHub Copilot.

import os
import tempfile
import unittest

from tmpl_survey import survey_dot


class TestTmplSurveyEdgeMode(unittest.TestCase):
    def test_write_edge_template_dot_file_labels_templates_on_edges(self):
        stack_counts = {
            ("מ:פסוק", "C/מ:כפול"): 3,
            ("מ:דחי", "C"): 4,
            ("מ:אות-ג", "C/מ:כפול/מ:פסוק"): 2,
            ("מ:אות-ג", "C/מ:פסוק"): 5,
        }

        with tempfile.TemporaryDirectory() as tdir:
            dot_path = os.path.join(tdir, "edge-mode.dot")
            survey_dot.write_edge_template_dot_file(stack_counts, dot_path)
            with open(dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn(
            '"C::start" -> "C::stack-end" [label="מ:דחי (4)"]',
            dot_text,
        )
        self.assertNotIn('"C::start" -> "C::stack-end" [label="מ:פסוק (3)"]', dot_text)
        self.assertIn(
            '"C::start::מ:פסוק" -> "C::stack::מ:פסוק" [label="מ:פסוק (7)"]', dot_text
        )
        self.assertIn(
            '"C::stack::מ:פסוק" -> "C::stack-end::מ:פסוק" [label="מ:אות-ג (7)"]',
            dot_text,
        )
        self.assertIn(
            '"C::stack-end" [label="end", tooltip="Stack end for C"]', dot_text
        )
        self.assertNotIn('"מ:פסוק";', dot_text)

    def test_write_edge_template_dot_file_applies_discard_set(self):
        stack_counts = {
            ("נוסח@1", "D"): 4,
            ("מ:פסוק", "D/נוסח@2"): 5,
        }

        with tempfile.TemporaryDirectory() as tdir:
            dot_path = os.path.join(tdir, "edge-mode.dot")
            survey_dot.write_edge_template_dot_file(stack_counts, dot_path)
            with open(dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn('"D::start" -> "D::stack-end" [label="מ:פסוק (5)"]', dot_text)
        self.assertNotIn('label="נוסח (', dot_text)
        self.assertNotIn('label="נוסח@', dot_text)
        self.assertIn("מ:כפול, נוסח have been discarded", dot_text)

    def test_write_edge_template_dot_file_includes_provenance(self):
        stack_counts = {
            ("מ:פסוק", "E"): 1,
        }

        with tempfile.TemporaryDirectory() as tdir:
            dot_path = os.path.join(tdir, "edge-mode.dot")
            survey_dot.write_edge_template_dot_file(
                stack_counts,
                dot_path,
                generator_file=__file__,
            )
            with open(dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn("generated by", dot_text)
        self.assertIn("graph [comment=", dot_text)

    def test_write_edge_template_dot_file_abbreviates_edge_labels_with_tooltips(self):
        stack_counts = {
            ("first middle final", "C"): 2,
            ("alpha beta gamma", "C/short name"): 1,
        }

        with tempfile.TemporaryDirectory() as tdir:
            dot_path = os.path.join(tdir, "edge-mode.dot")
            survey_dot.write_edge_template_dot_file(stack_counts, dot_path)
            with open(dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn(
            '"C::start" -> "C::stack-end" [label="first … final (2)", tooltip="first middle final (2)"]',
            dot_text,
        )
        self.assertIn(
            '"C::stack::short name" -> "C::stack-end::short name" [label="alpha … gamma (1)", tooltip="alpha beta gamma (1)"]',
            dot_text,
        )

    def test_write_edge_template_dot_file_compacts_long_one_hop_merged_labels(self):
        stack_counts = {
            ("a middle a", "C"): 1,
            ("b middle b", "C"): 1,
            ("c middle c", "C"): 1,
            ("d middle d", "C"): 1,
            ("e middle e", "C"): 1,
            ("f middle f", "C"): 1,
            ("g middle g", "C"): 1,
            ("h middle h", "C"): 1,
        }

        with tempfile.TemporaryDirectory() as tdir:
            dot_path = os.path.join(tdir, "edge-mode.dot")
            survey_dot.write_edge_template_dot_file(stack_counts, dot_path)
            with open(dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn(
            'label="a … a (1) | b … b (1) | … +6 more"',
            dot_text,
        )
        self.assertIn('tooltip="a middle a (1) | b middle b (1)', dot_text)
        self.assertIn("g middle g (1)", dot_text)
        self.assertIn("h middle h (1)", dot_text)


if __name__ == "__main__":
    unittest.main()
